from manim import *
import math
from math import pi


def _smart_text(text, font_size):
    """含非 ASCII 字符（中文/希腊字母/全角符号）用 Text（Pango 渲染，支持中文）；纯 ASCII 用 MathTex（LaTeX 渲染，支持数学公式）。"""
    return Text(text, font_size=font_size) if any(ord(c) > 127 for c in text) else MathTex(text, font_size=font_size)


class DefiniteIntegralScene(Scene):
    def construct(self):
        expr = {{func}}
        a = {{a}}
        b = {{b}}
        title_text = {{title}}

        axes = Axes(
            x_range=[-6, 6, 1],
            y_range=[-4, 4, 1],
            axis_config={"include_numbers": True, "font_size": 18},
        ).scale(0.9)
        self.play(Create(axes))

        f = lambda x: eval(expr, {"__builtins__": {}}, {"x": x, "np": np, "math": math, "pi": pi})
        graph = axes.plot(f, color=YELLOW)
        self.play(Create(graph))

        area = axes.get_area(graph, x_range=[a, b], color=BLUE, opacity=0.5)
        self.play(FadeIn(area), run_time=1.5)

        a_dot = Dot(axes.coords_to_point(a, 0), color=RED)
        b_dot = Dot(axes.coords_to_point(b, 0), color=RED)
        self.play(Create(a_dot), Create(b_dot))

        if title_text:
            integral = _smart_text(title_text, font_size=52).to_edge(UP)
            self.play(Write(integral))

        self.wait(2)
